lessons.syntax:
for (int i = 0; i < n; i++) {
    /* 重复 n 次 */
}

lessons.example:
#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 3; i++) {
        printf("%d\n", i);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n = 3;
    while (n > 0) {
        printf("%d ", n);
        n--;
    }
    printf("\n");
    return 0;
}

lessons.syntax:
do {
    /* 至少执行一次 */
} while (condition);

lessons.example:
#include <stdio.h>

int main(void) {
    int n = 0;
    do {
        printf("%d\n", n);
        n++;
    } while (n < 0);
    return 0;
}

#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 5; i++) {
        if (i == 3) { break; }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 6; i++) {
        if (i % 2 != 0) { continue; }
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>

int main(void) {
    int sum = 0;
    for (int i = 1; i <= 4; i++) { sum += i; }
    printf("%d\n", sum);
    return 0;
}

lessons.syntax:
for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) { /* 单元格 */ }
}

lessons.example:
#include <stdio.h>

int main(void) {
    for (int r = 0; r < 2; r++) {
        for (int c = 0; c < 3; c++) { printf("*"); }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int count = 0;
    while (1) {
        if (count == 3) { break; }
        count++;
    }
    printf("%d\n", count);
    return 0;
}

lessons.syntax:
for (int i = 0; i < n; i++) {
    if (x > 0) { sum += x; }
}

lessons.example:
#include <stdio.h>

int main(void) {
    int n, x, count = 0;
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &x) != 1) { return 1; }
        if (x > 0) { count++; }
    }
    printf("%d\n", count);
    return 0;
}
